#!/usr/bin/env bash
# Portable release: embedded reviewed changes; no credentials or production data.
# Run with: bash deploy-agentic-complete.sh
set -Eeuo pipefail
set +x
umask 077
for tool in git docker kubectl python3 tar gzip sha256sum; do
  command -v "$tool" >/dev/null || { echo "Missing required tool: $tool" >&2; exit 1; }
done
docker info >/dev/null
docker buildx version >/dev/null
export KUBE_CONTEXT="${KUBE_CONTEXT:-$(kubectl config current-context)}"
kubectl --context "$KUBE_CONTEXT" get node worker-99 >/dev/null
kubectl --context "$KUBE_CONTEXT" get namespace rag >/dev/null
export GITEA_BRANCH="${GITEA_BRANCH:-main}"
# Use a fresh checkout. Existing local projects are never overwritten.
RELEASE_CHECKOUT="$(mktemp -d "$PWD/agentic-release.XXXXXXXX")"
echo "Release checkout: $RELEASE_CHECKOUT"
git clone https://github.com/burodw1024/cloud.git "$RELEASE_CHECKOUT/project"
cd "$RELEASE_CHECKOUT/project"
git checkout -b onprem-release bb5aa7a41547b64c28ada462e5ebe5e0a3a4b2e3
# Restore the prepared Django/SQLite/MCP/Kubernetes changes into the clean base.
python3 - <<'RESTORE'
