"""
data = base64.b64decode(encoded)
if hashlib.sha256(data).hexdigest() != '24c4648c583e0481fb7b2f5776eae8f5ffc5c9fdf2658e1ae18ce24ecda27e8c':
    raise SystemExit('Embedded release checksum mismatch.')
root = Path.cwd().resolve()
with tarfile.open(fileobj=io.BytesIO(data), mode='r:gz') as archive:
    for member in archive.getmembers():
        destination = (root / member.name).resolve()
        if not destination.is_relative_to(root) or not member.isfile():
            raise SystemExit('Invalid embedded release member.')
    archive.extractall(root, filter='data')
print('Prepared project changes restored.')
RESTORE
# Configure Git author identity if this build machine has none. No credentials
# are embedded: use your existing Git/Docker credential stores.
if ! git var GIT_AUTHOR_IDENT >/dev/null 2>&1; then
  read -r -p 'Git commit author name: ' AUTHOR_NAME
  read -r -p 'Git commit author email: ' AUTHOR_EMAIL
  git config user.name "$AUTHOR_NAME"
  git config user.email "$AUTHOR_EMAIL"
fi
# The embedded launcher generates a private SQLite configuration when absent,
# prompts privately for the first administrator, and asks for the TLS Secret.
# It pushes to admin/agentic, builds/pushes registry images, backs up SQLite,
# migrates, deploys to worker-99 in rag, and waits for HTTPS readiness on 31135.
exec bash deploy/release-agentic.sh
